import { Suspense } from 'react'
import { cookies, headers } from 'next/headers'
import { cacheLife } from 'next/cache'
import { getProjectTotals } from '@/lib/projects'

export default function DashboardPage() {
  return (
    <main>
      {/* Cached dashboard frame: prerenders into the static shell and stays
          reusable across requests. Only the member details stream in. */}
      <DashboardFrame />

      {/* Request-specific content reads cookies()/headers(), so it must sit
          behind a Suspense boundary. The fallback keeps a useful frame
          visible while the member details load. */}
      <Suspense fallback={<MemberDetailsSkeleton />}>
        <MemberDetails />
      </Suspense>
    </main>
  )
}

/**
 * Reusable dashboard frame: the title and the shared project totals.
 * Cached with `use cache` so it prerenders into the static shell and is
 * served immediately on navigation.
 */
async function DashboardFrame() {
  'use cache'
  cacheLife('hours')

  const totals = await getProjectTotals()

  return (
    <section>
      <h1>Workspace</h1>
      <p>{totals.active} active projects</p>
    </section>
  )
}

/**
 * Request-specific member details: name, team, and request region.
 * Reads cookies()/headers(), so it runs at request time and streams in
 * behind the Suspense boundary above.
 */
async function MemberDetails() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const member = cookieStore.get('member')?.value ?? 'Guest'
  const team = cookieStore.get('team')?.value ?? 'Community'
  const region = requestHeaders.get('x-region') ?? 'global'

  return (
    <section>
      <p>Welcome, {member}</p>
      <p>Team: {team}</p>
      <p>Region: {region}</p>
    </section>
  )
}

function MemberDetailsSkeleton() {
  return (
    <section aria-busy="true">
      <p>Loading member details…</p>
    </section>
  )
}

